package ru.kstolu.app;
import android.graphics.*;import android.graphics.drawable.Drawable;
final class UiIcon extends Drawable {private final String name;private final int color,size;UiIcon(String n,int c,int s){name=n;color=c;size=s;setBounds(0,0,s,s);}public int getIntrinsicWidth(){return size;}public int getIntrinsicHeight(){return size;}public void setAlpha(int a){}public void setColorFilter(ColorFilter f){}public int getOpacity(){return PixelFormat.TRANSLUCENT;}public void draw(Canvas c){c.save();c.translate(getBounds().left,getBounds().top);c.scale(getBounds().width()/24f,getBounds().height()/24f);Paint p=new Paint(3);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(1.7f);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);Path path=new Path();switch(name){case "swap":path.moveTo(3,7);path.lineTo(20,7);path.lineTo(16,3);path.moveTo(21,17);path.lineTo(4,17);path.lineTo(8,21);break;case "help":c.drawCircle(12,12,9,p);path.moveTo(9,9);path.cubicTo(9,5,17,6,14,11);path.lineTo(12,13);c.drawPoint(12,17,p);break;case "home":path.moveTo(3,11);path.lineTo(12,3);path.lineTo(21,11);path.moveTo(5,10);path.lineTo(5,21);path.lineTo(19,21);path.lineTo(19,10);path.moveTo(10,21);path.lineTo(10,14);path.lineTo(14,14);path.lineTo(14,21);break;case "book":path.moveTo(6,3);path.lineTo(18,3);path.lineTo(18,21);path.lineTo(12,17);path.lineTo(6,21);path.close();break;case "camera":c.drawRoundRect(3,6,21,21,3,3,p);c.drawCircle(12,13,4,p);path.moveTo(8,6);path.lineTo(10,3);path.lineTo(14,3);path.lineTo(16,6);break;case "spark":path.moveTo(12,2);path.lineTo(15,9);path.lineTo(22,12);path.lineTo(15,15);path.lineTo(12,22);path.lineTo(9,15);path.lineTo(2,12);path.lineTo(9,9);path.close();break;case "back":path.moveTo(15,5);path.lineTo(8,12);path.lineTo(15,19);break;case "arrow":path.moveTo(9,5);path.lineTo(16,12);path.lineTo(9,19);break;case "settings":c.drawCircle(12,12,4,p);for(int i=0;i<8;i++){double a=i*Math.PI/4;c.drawLine(12+(float)Math.cos(a)*8,12+(float)Math.sin(a)*8,12+(float)Math.cos(a)*10,12+(float)Math.sin(a)*10,p);}break;default:c.drawRoundRect(6,3,18,21,1,1,p);for(int y=7;y<=15;y+=4)c.drawLine(9,y,15,y,p);}c.drawPath(path,p);c.restore();}}
